interface Point { x: number; y: number }

const a: Point = { x: 1, y: 2, z: 3 }; // error: 'z' does not exist in type 'Point'
const raw = { x: 1, y: 2, z: 3 };
const b: Point = raw;                  // ok: not a fresh literal
console.log(JSON.stringify(b));        // {"x":1,"y":2,"z":3}

type Animal = { name: string };
type Dog = Animal & { bark(): string };

const dogs: Dog[] = [{ name: 'Rex', bark: () => 'woof' }];
const animals: Animal[] = dogs; // allowed: arrays are covariant
animals.push({ name: 'Tom' });  // compiles, but dogs now holds a non-dog
dogs[1].bark();                 // TypeError at runtime

interface Strict { accept: (value: string | number) => void }
interface Loose { accept(value: string | number): void }

const onlyStrings = (value: string) => console.log(value.toUpperCase());
const s: Strict = { accept: onlyStrings }; // error under strictFunctionTypes
const l: Loose = { accept: onlyStrings };  // allowed: method parameters are bivariant

interface Producer<out T> { get: () => T }
interface Consumer<in T> { put: (value: T) => void }
interface Cell<in out T> { get: () => T; set: (value: T) => void }

declare const dogSource: Producer<Dog>;
const animalSource: Producer<Animal> = dogSource; // ok, covariant
declare const animalSink: Consumer<Animal>;
const dogSink: Consumer<Dog> = animalSink;        // ok, contravariant

