type Animal = { name: string };
type Dog = Animal & { bark(): string };

function names(list: readonly Animal[]): string[] {
  return list.map(a => a.name);
}

const dogs: Dog[] = [{ name: 'Rex', bark: () => 'woof' }];
names(dogs); // fine: readonly arrays are safely covariant

type Handler<in T> = (value: T) => void;
const logAnimal: Handler<Animal> = a => console.log(a.name);
const onDog: Handler<Dog> = logAnimal; // fine: contravariant parameter

