solution:
type Shape = Record<string, string>;

function matchesShape(shape: Shape, value: unknown, exact: boolean): boolean {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return false;
  const record = value as Record<string, unknown>;
  for (const [key, kind] of Object.entries(shape)) {
    if (!Object.prototype.hasOwnProperty.call(record, key)) return false;
    if (typeof record[key] !== kind) return false;
  }
  // Structural typing allows extra keys; an exact check is like an excess property check.
  return !exact || Object.keys(record).every(key => Object.prototype.hasOwnProperty.call(shape, key));
}

