type Name = 'never' | 'Dog' | 'Cat' | 'Animal' | 'unknown';
type Fn = { param: Name; ret: Name };

const parent: Partial<Record<Name, Name>> = { Dog: 'Animal', Cat: 'Animal', Animal: 'unknown' };

function isSub(a: Name, b: Name): boolean {
  if (a === b || a === 'never' || b === 'unknown') return true;
  const up = parent[a];
  return up !== undefined && isSub(up, b);
}

function canAssign(target: Fn, source: Fn, method: boolean): boolean {
  const returns = isSub(source.ret, target.ret);
  const params = method
    ? isSub(target.param, source.param) || isSub(source.param, target.param)
    : isSub(target.param, source.param);
  return returns && params;
}

